                dest[pos++] = '0';

            //Now write the value itself. int.TryFormat to Span<char> is not available in .NET Standard 2.0

            for (var i = numChars - 1; i >= 0; i--)
            {
                var shift = i * 4;
                var val = (value >> shift) & 0xF;

                if (val < 10)
                    dest[pos++] = ((char) ('0' + val));
