                if (index == 0)
                {
                    switch (span[0])
                    {
                        case '\n':
                            Append("\\n");
                            break;

                        case '\r':
                            Append("\\r");
                            break;

                        case '\0':
                            Append("\\0");
                            break;

                        case '\t':
                            Append("\\t");
                            break;

                        default:
                            Debug.Assert(false);
                            break;
                    }

                    span = span.Slice(1);
                }
                else
                {
                    Append(span.Slice(0, index));
                    span = span.Slice(index);
                }
            }

            //Append anything remaining
            Append(span);
        }

