        public void Replace(char oldChar, char newChar, int startIndex, int count)
        {
            var currentLength = Length;

            if (startIndex > currentLength)
                throw new ArgumentOutOfRangeException();

            if (count < 0 || startIndex > currentLength - count)
                throw new ArgumentOutOfRangeException();

            var chars = _chars;

            for (var i = startIndex; i < startIndex + count; i++)
            {
                if (chars[i] == oldChar)
                    chars[i] = newChar;
            }
        }

        public void Replace(ReadOnlySpan<char> oldValue, ReadOnlySpan<char> newValue, int startIndex, int count)
        {
            var overallSpan = _chars.AsSpan(startIndex, count);

            using var indices = new ValueList<int>();

            var pos = 0;

            while (pos < overallSpan.Length)
            {
                var index = overallSpan.Slice(pos).IndexOf(oldValue);

                if (index == -1)
                    break;

                var matchIndex = pos + index;
                indices.Add(matchIndex);

                pos = matchIndex + oldValue.Length;
            }

            if (indices.Count == 0)
                return;

            if (newValue.Length > oldValue.Length)
            {
                var extraBytesPerItem = newValue.Length - oldValue.Length;
                var numNewChars = extraBytesPerItem * indices.Count;
                var originalLength = Length;
                EnsureCapacity(originalLength + numNewChars);
                _pos += numNewChars;

                var chars = _chars;

                var shiftRemaining = numNewChars;

                for (var i = indices.Count - 1; i >= 0; i--)
                {
                    var valueToReplaceStartIndex = indices[i] + startIndex;
                    var valueToReplaceLength = oldValue.Length;

                    var valueToReplace = chars.AsSpan(valueToReplaceStartIndex, valueToReplaceLength);

                    var contentAfterValueStartIndex = valueToReplaceStartIndex + valueToReplaceLength;
                    var contentAfterValueLength = (i < indices.Count - 1 ? indices[i + 1] : originalLength) - contentAfterValueStartIndex;

                    var contentAfterValue = chars.AsSpan(contentAfterValueStartIndex, contentAfterValueLength);

                    if (contentAfterValueLength > 0)
                    {
                        contentAfterValue.CopyTo(chars.AsSpan(contentAfterValueStartIndex + shiftRemaining));
#if DEBUG
                        //For debugging
                        //contentAfterValue.Clear();
#endif
                    }

                    shiftRemaining -= extraBytesPerItem;
                    var newValueRegion = chars.AsSpan(valueToReplaceStartIndex + shiftRemaining, newValue.Length);
                    newValue.CopyTo(newValueRegion);

#if DEBUG
                    //For debugging
                    //valueToReplace.Clear();
#endif
                    
                }
            }
            else if (newValue.Length == oldValue.Length)
            {
                //Overwrite each occurrence with the new value

                for (var i = 0; i < indices.Count; i++)
                    newValue.CopyTo(overallSpan.Slice(indices[i], newValue.Length));
            }
            else
            {
                //Write the new values directly. We can immediately start by writing the first value over
                //the first match

                var spanToEnd = _chars.AsSpan(startIndex, Length - startIndex);

                var newPos = 0;

                var diff = oldValue.Length - newValue.Length;

                for (var i = 0; i < indices.Count; i++)
                {
                    var index = indices[i];

                    var destPos = index - newPos;

                    newValue.CopyTo(spanToEnd.Slice(destPos, newValue.Length));

                    //Shift everything between this item and the one after it down

                    var gapStart = index + oldValue.Length;
                    var gapEnd = (i < indices.Count - 1 ? indices[i + 1] : spanToEnd.Length);

                    var gapLength = gapEnd - gapStart;

                    if (gapLength > 0)
                        spanToEnd.Slice(gapStart, gapLength).CopyTo(spanToEnd.Slice(destPos + newValue.Length));

                    newPos += diff;
                }

                Length -= diff * indices.Count;
            }
        }

